package com.cutedino.xiangsuplayer.core.phone

/** Same-origin client only. The original token-protected JSON route is unchanged. */
internal object PhonePairingPage {
    val html = """<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>像素播放器 TV · 手机输入</title>
<style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0f1827;color:#f4f7fc;font:18px/1.6 system-ui,sans-serif}main{max-width:680px;margin:auto;padding:32px 24px}h1{font-size:30px;line-height:1.3}p{color:#b8c8dd}label{display:block;margin:24px 0 8px}input,button{font:inherit;border-radius:6px;min-height:52px}input{width:100%;padding:12px;background:#162236;border:1px solid #71849b;color:inherit}button{padding:12px 20px;border:0;background:#b8d4f5;color:#0f1827;cursor:pointer;margin-top:16px}button:disabled{opacity:.6;cursor:wait}:focus-visible{outline:3px solid #f4f7fc;outline-offset:4px}#results button{display:block;text-align:left;width:100%;background:#25354a;color:#f4f7fc}#status{min-height:60px}</style>
<main><h1>像素播放器 TV</h1><p id="hint">同一局域网 · 本次配对五分钟内有效</p><form id="form"><label for="query">歌名、歌手或专辑</label><input id="query" name="query" maxlength="160" required autocomplete="off"><button id="submit" type="submit">发送到电视</button></form><p id="status" role="status" aria-live="polite">正在连接电视…</p><div id="results"></div></main>
<script>
const base=location.pathname.slice(0,-7),form=document.getElementById('form'),query=document.getElementById('query'),status=document.getElementById('status'),results=document.getElementById('results');let mode='input';
const messages={received:'已发送到电视，可返回电视继续搜索',ordered:'已加入点歌队列',queue_unavailable:'队列已满或已退出点歌，请在电视上查看',expired_choice:'结果已过期，请重新搜索',search_busy:'正在搜索，请稍后再试',search_timeout:'搜索超时，请重试',input_timeout:'电视暂未响应，请重试',invalid_pairing:'配对已结束，请在电视上重新生成二维码',expired_pairing:'配对已结束，请重新配对',order_timeout:'点歌暂未完成，请查看电视队列后重试'};
async function send(key,value){document.querySelectorAll('button').forEach(b=>b.disabled=true);status.textContent=key==='choice'?'正在加入队列…':mode==='order'?'正在搜索…':'正在发送…';try{const body=new URLSearchParams();body.set(key,value);const response=await fetch(base,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:body.toString()});const data=await response.json();if(data.status==='results'){results.replaceChildren();status.textContent=data.choices.length?'选择一首加入电视队列':'没有找到结果，请换个关键词';for(const choice of data.choices){const button=document.createElement('button');button.type='button';button.textContent=choice.label;button.onclick=()=>send('choice',choice.id);results.appendChild(button);}}else status.textContent=messages[data.status]||'暂未完成，请重试';}catch(e){status.textContent='无法连接电视，请确认同网或重新配对';}finally{document.querySelectorAll('button').forEach(b=>b.disabled=false);}}
form.onsubmit=e=>{e.preventDefault();const value=query.value.trim();if(value)send('query',value);};
fetch(base).then(r=>r.json()).then(data=>{mode=data.mode||'input';document.getElementById('submit').textContent=mode==='order'?'搜索歌曲':'发送到电视';status.textContent=data.status==='ready'?(mode==='order'?'搜索后选择歌曲即可点歌':'输入后发送，电视上可继续编辑'):(messages[data.status]||'配对不可用，请重试');}).catch(()=>{status.textContent='无法连接电视，请重新配对';});
</script></html>""".trimIndent()
}
